import{_ as a,o as e,c as r,ag as s}from"./chunks/framework.C5oN-8Wt.js";const n="/cns_master_docs/teaching-v0.2.0-alpha/05-noise.svg",u=JSON.parse('{"title":"05 信号遇到噪声：还能认出原来的变化吗？","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/learn/05-noise/index.md","filePath":"v0.2.0-alpha/learn/05-noise/index.md"}'),o={name:"v0.2.0-alpha/learn/05-noise/index.md"};function i(l,t,d,h,p,c){return e(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="_05-信号遇到噪声-还能认出原来的变化吗" tabindex="-1">05 信号遇到噪声：还能认出原来的变化吗？ <a class="header-anchor" href="#_05-信号遇到噪声-还能认出原来的变化吗" aria-label="Permalink to &quot;05 信号遇到噪声：还能认出原来的变化吗？&quot;">​</a></h1><p>无人机向地面发送状态时，接收设备得到的信号可能夹杂随机扰动。这里先把问题缩小：在一条已知的周期信号上加噪声，观察哪些特征仍容易辨认。<strong>本例生成软件信号，不连接无人机，也不模拟某一种实际无线电设备。</strong></p><p>适用 CNS Master <strong>v0.2.0-alpha</strong>。先完成<a href="./../04-signal-views/">04 时域、频域与瀑布</a>。</p><p><a href="../../../downloads/teaching-v0.2.0-alpha/05-noise.cnsproj" download>下载本课工程：05-noise.cnsproj</a></p><h2 id="这一课要弄明白什么" tabindex="-1">这一课要弄明白什么 <a class="header-anchor" href="#这一课要弄明白什么" aria-label="Permalink to &quot;这一课要弄明白什么&quot;">​</a></h2><ul><li>区分有固定周期的信号与没有固定周期的随机噪声。</li><li>在相同坐标刻度下比较原信号、噪声和相加结果。</li><li>只改变噪声幅度，解释“更难看清”的具体含义。</li></ul><p>先回顾两个词：<strong>噪声</strong>是本例额外加入的随机数序列；<strong>高斯分布</strong>表示随机值较常靠近中心、离中心较远的值较少。它不是“只会在某两个边界内变化”。本例的幅度均为归一化数值，不是伏特。</p><h2 id="工程怎样接线-参数为什么这样选" tabindex="-1">工程怎样接线，参数为什么这样选 <a class="header-anchor" href="#工程怎样接线-参数为什么这样选" aria-label="Permalink to &quot;工程怎样接线，参数为什么这样选&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信号源 1.out ──→ 加法器 1.in1</span></span>
<span class="line"><span>噪声源 1.out ──→ 加法器 1.in2</span></span>
<span class="line"><span>                  加法器 1.out ──→ 混合信号</span></span></code></pre></div><p>观察器从输出端取数据，不需要把观察器画成另一个计算节点。加法器在同一采样时刻把两路数值相加，原信号支路仍可独立观察。</p><table tabindex="0"><thead><tr><th>位置</th><th>本课值</th><th>选择理由</th></tr></thead><tbody><tr><td>信号源 1</td><td>正弦；64 Hz；幅度 1；初相 0；偏置 0</td><td>先用容易辨认的周期变化作参照</td></tr><tr><td>噪声源 1</td><td>高斯；噪声幅度 0.2；固定种子 7</td><td>扰动较小；重新准备时可从同一随机起点对照</td></tr><tr><td>两个源的采样率</td><td>都为 4096 Hz，即每秒 4096 个标量样本</td><td>两路同速，才能按同一时刻相加；正弦每周期有 64 点</td></tr><tr><td>加法器 1</td><td>2 路输入，其余保持工程值</td><td>只研究一次相加，不混入额外处理</td></tr></tbody></table><p><strong>噪声幅度 0.2 不是 0.2 dB，也不是信噪比。</strong> 信噪比要比较信号与噪声的功率，并说明测量带宽；本课暂不据这个参数计算实际无线链路质量。</p><h2 id="跟着做" tabindex="-1">跟着做 <a class="header-anchor" href="#跟着做" aria-label="Permalink to &quot;跟着做&quot;">​</a></h2><ol><li>将工程下载到个人文件夹。在 Master 中先按 <strong>Shift+F5</strong> 停止其他本地实验，再用“文件 → 打开工程”（Ctrl+O）选择文件。若提示未保存修改，先处理自己的工程。</li><li>选中两个源，核对上表。先预测：相加后波形的周期骨架会消失，还是只会变得不平整？</li><li>按 <strong>F5</strong> 运行。工程已保存观察器绑定。打开观察器的“参数”页，确认时域捕获包括“信号源 1 → 输出”和“加法器 1 → 输出”。若窗口被遮住，用“视图 → 分析工具”找到它。</li><li>如需自己重建观察器，用“编辑 → 插入 → 观察器”；在“参数”页点击“添加捕获变量”，输入模块名，<strong>点选候选</strong>完成绑定。输入框中仅写下文字还没有绑定。两路均选普通输出，不选“频谱”。</li><li>回到“输出”页，使用“曲线叠加”。先点“自动刻度”，再把横轴缩到约 <strong>0.0625 s</strong> 的全宽，能看到约四个 64 Hz 周期。两路单位相同，应共用纵轴；不要把它们分别缩放到看起来一样高。</li><li>在单独的噪声观察器看“噪声源 1 → 输出”。需要细看时，左键横向拖动图像进入定格回看；此时计算仍在继续。点击“自动刻度”返回最新数据。</li><li>按 <strong>Shift+F5</strong> 停止。保留实际收到的数据，记录一段波形的总时长、纵轴范围与自己的观察。</li></ol><h2 id="应该看到的图像-怎样解释" tabindex="-1">应该看到的图像，怎样解释 <a class="header-anchor" href="#应该看到的图像-怎样解释" aria-label="Permalink to &quot;应该看到的图像，怎样解释&quot;">​</a></h2><p><a href="/cns_master_docs/teaching-v0.2.0-alpha/05-noise.svg"><img src="`+n+'" alt="实际 GNU 输出与单参数对照：固定种子下噪声幅度从 0.2 增加为 0.8"></a></p><p>左图比较原信号与加入噪声后的输出，右图比较两种噪声幅度。噪声增大后，曲线偏离原正弦的程度通常更大；每个时刻的偏差仍是随机的。</p><p>原信号有规则的波峰与波谷。混合信号围绕它上下扰动，在噪声幅度 0.2 的这一组条件下，通常仍容易辨认约 <strong>15.625 ms</strong> 一个周期的整体变化；个别采样点可能偏离较远。</p><p>噪声单独显示时，不能像正弦一样找出一个稳定的重复周期。它的有限时段频谱也会起伏；“高斯”描述随机值的分布，不保证每一帧频谱都平坦。</p><p>如果把混合输出绑定到另一个观察器的“频谱”变量，可以看到 64 Hz 附近的信号成分和分散的噪声背景。它们处于同一段采样数据中，不代表软件识别出了“真实遥测信息”。</p><h2 id="单参数对照-只把噪声幅度改成-0-8" tabindex="-1">单参数对照：只把噪声幅度改成 0.8 <a class="header-anchor" href="#单参数对照-只把噪声幅度改成-0-8" aria-label="Permalink to &quot;单参数对照：只把噪声幅度改成 0.8&quot;">​</a></h2><ol><li>停止后，把噪声源 1 的“噪声幅度”从 <strong>0.2 改为 0.8</strong>；分布、种子、信号源、采样率均不动。</li><li>重新按 F5 运行，沿用刚才的横轴、纵轴范围。若超出图框，可扩大纵轴，但两轮比较要采用同一范围。</li><li>记录：扰动是更大了，还是周期变快了？64 Hz 信号本身的频率有没有改变？</li><li>恢复 0.2，再次停止并运行。固定种子用于对照相同起点；连续运行中等待更久，会看到序列后面的新样本。</li></ol><p>预期是噪声起伏增大，信号的 64 Hz 参数不变。不要因混合曲线过零次数变多，就把它解释为“原信号频率升高”。</p><h2 id="遇到问题先检查" tabindex="-1">遇到问题先检查 <a class="header-anchor" href="#遇到问题先检查" aria-label="Permalink to &quot;遇到问题先检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>检查方法</th></tr></thead><tbody><tr><td>两条曲线完全重合</td><td>核对噪声幅度是否为 0、是否两次都绑定到了信号源，以及改动后是否重新运行</td></tr><tr><td>两轮看起来差不多高</td><td>自动纵轴可能分别缩放了图像；比较纵轴数字，再用相同范围观察</td></tr><tr><td>固定种子仍看到不同曲线</td><td>比较是否从同一次启动的相同采样位置取数；连续运行不会反复显示开头</td></tr><tr><td>观察器一直等待</td><td>确认本地任务已运行、绑定的是本工程变量，并点击候选完成选择</td></tr></tbody></table><p>本例说明加性随机扰动的外观，没有模拟丢包、网络延迟、遮挡衰落、蜂窝切换或实际接收机。下一课研究：知道需要保留的频率范围后，<a href="./../06-filter/">滤波能帮上什么忙</a>。</p><p>模块参考：<a href="./../../modules/noise_source/">噪声源</a> · <a href="./../../modules/add/">加法器</a> · <a href="./../">返回学习路径</a></p>',27)])])}const _=a(o,[["render",i]]);export{u as __pageData,_ as default};
